-- Rifts World Book 34: Northern Gun Two, five robot drones (printed 244-251): NG-PD12 Fido, NG-CDH30 Mule, NG-W9 Light Labor Drone, NG-W10 Heavy Labor Drone, NG-WD71 Robosistant
-- 5 vehicle rows, with 30 locations and 7 weapon entries.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~330-northern-gun-2-drones-b.sql
--
-- Written by scripts/vessel-sql.mjs from 1 worker file(s). Every value
-- is printable ASCII, every row cites its book, and a Main Body location
-- agrees with its vehicle's mdc_main_body.

INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('ng-pd12-fido', 'NG-PD12 "Fido" Personal Cargo Drone', 'rifts', 'drone', 'None: an unmanned drone that follows voice or remote commands.', 'None.', 'Up to 35 mph (56 km) over most terrain, woodland and thick brush included; half speed wading chest-deep (2 ft/0.6 m) water, snow or mud; 6 mph (9.6 km) on ice. Leaps 5 ft (1.5 m) high and 10 ft (3 m) across, half again more with a running start. Range unlimited.', 'Cannot fly.', 'Cannot swim. Wades 2.5 ft (0.76 m) with the cargo kept dry, and walks a lake floor at 5 mph (8 km) to a printed 1,000 ft (the metric figure, 30.5 m, would be 100 ft).', 'Height 3 ft (0.9 m) at the head, 28 in (71 cm) at the cargo platform; width 2 ft (0.6 m); length 4.6 ft (1.4 m)', '200 lbs (90 kg)', 110, 1, NULL, 525000, '525,000 credits Solid Oxide, 825,000 nuclear (10 year life). The Drone Control and Command Gauntlet is extra (a gear row).', 'Model NG-PD12, classed as an unmanned personal cargo carrier, from designers Kerry Reed, Christina Liu and David Nemoseck. A dog-shaped pack robot sold or rented to adventurers, explorers and messengers who travel light and would rather not feed a pack animal. Its four legs cope with rough ground, stairs, moderate slopes and narrow mountain trails, and at the size of a big dog it goes where bigger haulers cannot: into buildings and elevators, up to a hotel room, down caves and tunnels. Most places that bar robots let Fido in. Bags, bedrolls, cases and satchels hang from hooks and tie-downs on its back, and the rump container holds two straps that clip to the shoulders. It barks at danger and growls at strangers who come near or reach for the cargo. The two round eyes are headlights, the ear fins are communications antennae, and each long cheek plate holds front and rear cameras and swings out to expose a small laser. Control: voice recognition answers the owner and up to three authorized users and is not fooled by imitation; a notebook-sized touch-screen control pad drives that one unit, and NG''s Drone Control and Command Gauntlet (a gear row) runs up to ten. The controller can take over and drive it remotely by instruments and live video. Sensors: as robot vehicles but with no life support, crew space, radar or combat systems; everything sits in the head, the optics in the nose. Communications 5 miles (8 km), audio and video. Seven cameras: the four in the cheek units have passive nightvision to 500 ft (152 m), 8x telescopic zoom to 1,000 ft (305 m) and 8x macro, and there are plain ones in each shoulder and the chest; live feed 5 miles (8 km), 96 hours of video and 4,000 stills. Two telescoping utility arms on the front legs (reach 2 ft/0.6 m, Robot P.S. 12) push branches aside and fetch or hand over small, light things; they cannot fight or fire a weapon. Cargo: up to 800 lbs (360 kg) tied on its back or hung from its neck (the page prints 360 km). Power: Solid Oxide or nuclear only.', 'Rifts World Book 34: Northern Gun Two p.244-245'),
  ('ng-cdh30-mule', 'NG-CDH30 "Mule" Cargo Hauler (Walking Table)', 'rifts', 'drone', 'None: an unmanned, remote-controlled drone.', 'None; it can carry one or two casualties or rescued people on its table top.', 'Up to 30 mph (48 km) on roads, grass and stony or sandy desert, and it handles sand well; half that through thick brush, forest and rocky trails or wading 2.5 ft (0.76 m) of water, snow or mud; 8 mph (12.8 km) on ice. It struggles in woods without a trail, and loads snag on brush. Cannot leap. Range unlimited.', 'Cannot fly.', 'Cannot swim. Wades 2.5 ft (0.76 m) with the cargo kept dry and walks a lake floor down to 500 ft (152 m).', 'Standard NG-CDH30: height 4 ft (1.2 m), width 4 ft (1.2 m), length 8 ft (2.4 m). Large NG-CDH33: height 4.6 ft (1.4 m), width 8 ft (2.4 m), length 22 ft (6.7 m)', '1,000 lbs (450 kg) standard; 2,000 lbs (900 kg) large (whose weight line calls it 26 ft/22.6 m long)', 150, 1, NULL, 790000, 'Standard NG-CDH30: 790,000 credits Solid Oxide, 1.1 million nuclear (about 10 year life). Large NG-CDH33: 2.1 million Solid Oxide, 2.5 million nuclear.', 'Models NG-CDH30 (standard, the common one) and NG-CDH33 (large), unmanned automated cargo robots nicknamed Walking Tables, from lead designers Dan DeLuca, Scott Gibbons and James Grey. A flat, railed load bed with tie-down points and drain holes, walking on six legs, or eight on the large model, which is the only other difference. Both are very rugged. Built to follow infantry, explorers and adventurers and carry their heavy kit, it stays narrow and low enough for hallways and stairwells, and its legs pick their way around obstacles on broken ground. It takes voice and wireless orders like Fido: in a combat unit one to ten haulers answer to one NCO (a corporal or sergeant) who wears the Drone Control and Command Gauntlet, with the squad leader or lieutenant and one more person as backups. It hauls spare weapons, ammunition and gear, takes one or two wounded to a medic or civilians to safety, and its bare top serves as a workbench, operating table or bed. It can also crouch, slip the table edge under a vehicle and lift it like a jack for a tire change or work underneath, though a hard bump may tip the vehicle off. Cargo: 4 tons standard, 16 tons large. Sensors: as Fido, without the barking or the lasers, all in the sensor pod. Lights: two at each end under the table, set 8 in (20 cm) back on swivel mounts moving 30 degrees side to side and up and down, 500 ft (152 m) beam. It has no artificial intelligence: it obeys the voice or radioed orders of its operator and 2-3 backups, or heads for set coordinates, and the operator can take over and drive it remotely by instruments and live video. Weapons: none. Power: nuclear (about 10 year life) or Solid Oxide.', 'Rifts World Book 34: Northern Gun Two p.245-246'),
  ('ng-w9-light-labor-drone', 'NG-W9 Light Labor Drone', 'rifts', 'drone', 'None: a robot with simple artificial intelligence.', 'None.', 'Runs at up to 50 mph (80 km) without tiring, indefinitely. Leaps 12 ft (3.7 m) high or across, 10 ft (3 m) more from a run faster than 40 mph (64 km).', 'Cannot fly.', 'Walks lake and sea floors at 15 mph (24 km) and swims at 10 mph (16 km, 9 knots); can use underwater vehicles and equipment. Depth tolerance 1,000 ft (305 m).', 'Height 6.6 ft (2 m); width 3 ft (0.9 m); length 2.5 ft (0.76 m)', '800 lbs (360 kg)', 100, 1, NULL, 1700000, '1.7 million credits Solid Oxide, 2 million nuclear (about 5 year life), the labor program and laser finger included. Good availability. Other labor programs 40,000-240,000 credits or more; the military combat program 325,000.', 'Model NG-W9, a fully automated, self-sufficient labor robot. All over Ishpeming these man-sized robots work in factories, on docks and farms, haul and deliver freight, stand sentry, serve as target drones, fight fires and handle hazardous material; they get the dirtiest, riskiest jobs, above all making Solid Oxide batteries and nuclear power cores. A strong seller: it works twenty hours a day, needs no food, pay or encouragement and keeps its quality steady, but should cool down four hours a day or its internals may burn out. Its M.D.C. is kept low on purpose, and its simple AI cannot fight unless a military program replaces the labor one. Robot P.S. 24. Labor program: Math: Basic 96%; American, Spanish and Techno-Can at 92%; cleaning, digging, loading, running machines and common tools; it carries 1,000 lbs (450 kg) at half speed and lifts twice that. Two more programs from: Domestic Services (Cooking 85%, First Aid 90%, Housekeeping 90%, Math: Basic 96%, Preserve Food 90%, Radio: Basic 90%, Recycling 92%, Sewing 92%, Wardrobe & Grooming 92%); General Labor (Computer Operation 96%, General Repair and Maintenance 90%, Pilot: Automobile or Hover Craft 90%, Pilot: Truck 90%); Farmhand (Animal Husbandry 65%, Branding 88%, Herding Cattle 80%, Horsemanship: General 60% on robot or other mounts able to bear 800 lbs/360 kg, Identify Plants & Fruits 92%, Lore: Cattle & Animals 92%, Pilot: Truck 92%, Rope Works 92%); Mechanics (Aircraft Mechanics 70%, Automotive Mechanics 80%, Basic Electronics 85%, Basic Mechanics 90%, Computer Operation 90%, General Repair and Maintenance 90%, Salvage 75%); Transportation (Pilot: Automobile 96%, Hover Craft 90%, Truck 90%, and three more at 88%, none military, robot or recreational); Woodworking (Art 50%, Carpentry 88%, Rope Works 90%, Whittling & Sculpting 70%). Sensors: visible-light, infrared and ultraviolet optics with glare filters; hearing as faint as 10 decibels at 500 ft (152 m) and into the ultrasonic, recognizing 60,000 machine sounds; a short-range directional radio, 5 miles (the page prints 8 m). Speech: no conversation, only short stock replies and warnings, by voice synthesizer or radio. Optional military program: outlawed in most civilized nations, among them Lazlo, Kingsdale, Whykin, Free Quebec and the Coalition States, and under debate in Ishpeming and Manistique; cruder and more reactive than Triax or NGR programs, it suits sentry, escort, border patrol, infantry and seek-and-destroy work. It gives Climb 96%/86%, Computer Operation 96%, General Repair & Maintenance 80%, Intelligence 85%, Land Navigation 90%, Math: Basic 96%, Military Etiquette 96%, Parachuting 90%, Pilot: Boat, Motor Type 86%, Pilot: Hover Craft 96%, Radio: Basic 96%, its three languages at 90%, and W.P. Paired Weapons, Blunt, Knife or Sword, Rifles, Energy Pistol, and Energy Rifle or Heavy M.D. Weapons. Power: nuclear (about 5 year life) or Solid Oxide.', 'Rifts World Book 34: Northern Gun Two p.246-248'),
  ('ng-w10-heavy-labor-drone', 'NG-W10 Heavy Labor Drone', 'rifts', 'drone', 'None: a robot drone with simple intelligence.', 'None.', 'Runs at up to 40 mph (64 km) without tiring, indefinitely. Tunnels 1D6x5 yards/meters an hour, slower when prospecting. Leaps 10 ft (3 m) high or across standing, 20 ft (6.1 m) high or 30 ft (9.1 m) across with a running start.', 'Cannot fly.', 'Walks lake and sea floors at 15 mph (24 km) and swims at 10 mph (16 km, 9 knots); can use underwater vehicles and equipment. Depth tolerance 2,000 ft (610 m).', 'Height 10 ft 5 in (3.2 m); width 4 ft (1.2 m); length 3 ft (0.9 m)', '1,200 lbs (540 kg)', 120, 1, NULL, 4000000, '4 million credits Solid Oxide, 4.5 million nuclear (about 5 year life even in constant use); used or refurbished nuclear units 2-3 million. Good availability wherever NG sells. A skilled robot builder can armor it further, at most +40 M.D.C. on the main body and +15 on the head, for about 650,000.', 'Model NG-W10, a fully automated, self-sufficient labor robot: the W9''s bigger, tougher cousin, shaped like a scaled-down V-10 Super, the robot vehicle NG means to stop making around 110 P.A. Unarmed and able to work long stretches unsupervised, it is meant for mining, large building projects and labor in places where monsters and supernatural beings attack. Robot P.S. 32. Labor program: as the NG-W9, but with three extra programs instead of two, which may include two of its own: Mining (Excavation 85%, Mining 90%, Pilot: Truck 92%, Recycling 88%, Rope Works 88%, Salvage 80%, plus how to dig tunnels, brace walls and ceilings and ventilate them, and recognize 600 minerals as well as oil, coal and gas deposits) and Specialized Heavy Labor (Carpentry 85%, Demolitions and Demolitions Disposal 85%, Firefighting 80%, Masonry 80%, Rope Works 88%, Salvage 90%). It never tires, carries one ton (2,000 lbs/900 kg) and lifts two. Sensors: as the NG-W9. It cannot wear extra body or power armor. The optional military program works as for the W9 and is illegal in the Coalition States. Power: nuclear (about 5 years in constant use) or Solid Oxide.', 'Rifts World Book 34: Northern Gun Two p.248-249'),
  ('ng-wd71-robosistant', 'NG-WD71 Robosistant', 'rifts', 'drone', 'None: a repair robot with artificial intelligence.', 'None.', 'Runs at up to 35 mph (56 km) on roads, grass and stony or sandy desert without tiring; half that through thick brush, forest and rocky trails or water, snow or mud over 1 ft (0.3 m) deep; 6 mph (9.6 km) on ice. It travels much as a person does, but should rest 4 hours a day to avoid overheating. Cannot leap.', 'Cannot fly.', 'Cannot swim; walks a lake floor to 500 ft (152 m).', 'Height 5 ft (1.5 m); width 2.5 ft (0.76 m); length 3 ft (0.9 m)', '580 lbs (261 kg)', 125, 1, NULL, 2000000, '2 million credits electric battery, 2.6 million Solid Oxide, 3 million nuclear (10 year life), all with the standard tools, lights, sensors and labor programming.', 'Model NG-WD71, a fully automated, self-sufficient repair robot from lead designers Brendan Blackmer, Ryan Rawlings, Rick Bray and Lestor Calwhan, released in summer 107 P.A. and steadily more popular. Meant as more than a remote puppet or hauler but less than a true companion: a tireless extra pair of hands for Operators, mechanics and lab staff. Its multi-tool arms carry a welding and cutting torch, soldering iron, drill with bits, sockets and screwdrivers, hacksaw, small grinder, flashlight, laser pointer, a camera with 12x macro lens, and a hose spraying water or solvent; its hands are deft enough for computers, radios, power tools, wiring and small machine parts. It strips down fiddly machinery, tests parts and preps jobs before the mechanic arrives, saving many man-hours on war machines. In the field it gathers wood, tends a campfire, carries gear, pitches tents, builds shelters and radio masts, fixes flats, fetches water, clears trails and the road, and keeps watch overnight; it can use handheld tools too. A miner''s lamp tops its head and two small lights sit in its chest; five cameras record and send video and sound: two in the head, a third in the chest and one per forearm. Common across Upper Michigan, in the shops and factories of Ishpeming, Escanaba, Menominee and Marquette, and with Operators, Body Fixers, Cyber-Docs, scientists, explorers, mercenaries and adventurers who can pay for one, though owning one marks you as rich and draws bandits. Robot P.S. 24; it carries 250 lbs (112 kg) in its arms or 600 lbs (270 kg) on its back, lifts 1,000 lbs (450 kg) and pulls a ton. Weapons: none, and it will not turn its tools on anyone, even in self-defense, without heavy reprogramming. Speech: polite and natural-sounding in a male or female voice, but still short, simple replies; it cannot hold a real conversation. Program: Automotive Mechanics 90%, Basic Electronics 90%, Basic Mechanics 90%, Computer Operation 96%, Firefighting 88%, General Repair and Maintenance 90%, American, French and Techno-Can at 96%, Math: Basic 98%, Pilot: Boats/Paddle Types 96%, Pilot: Trucks 90%, Radio: Basic 90%, Recycling 96%, Rope Works 92%, Salvage 80%, TV/Video 90%, Vehicle Armorer 80%, Wardrobe & Grooming 92%, Wilderness Survival 90%, and general labor; no hand to hand or W.P.s, and it cannot even use a gun. Sensors: as robot vehicles but with no life support, crew space, radar or combat systems, all in the head. Optics: visible, infrared, ultraviolet and polarizing filters, passive nightvision to 1,000 ft (305 m), 12x telescopic zoom to 2 miles (3.2 km), 8x macro, video sent 5 miles (8 km), 96 hours of video and 4,000 stills. Voice recognition answers its owner and up to eight authorized users and is not fooled by imitation; the Drone Control and Command Gauntlet (a gear row) sends it silent orders. It knows gunfire, engine noise and faults, alarms and the calls of dangerous animals, and hears anger, distress or laughter in voices, offering help or comfort. It recognizes 3,000 friendly and 3,000 hostile faces cleared by its owner, greeting known people by name, plus 10,000 dangerous North American animals and monsters; more can be added. Power: nuclear (10 years), Solid Oxide or electric battery.', 'Rifts World Book 34: Northern Gun Two p.249-251');

INSERT OR IGNORE INTO vehicle_locations (vehicle_slug, location, mdc, mdc_note, ordinal) VALUES
  ('ng-pd12-fido', 'Headlights (2)', 5, 'Each. Small target: Called Shot, -4 to strike.', 1),
  ('ng-pd12-fido', 'Head', 90, 'Small target: Called Shot, -4 to strike. Holds the communications, optics and sensors; destroyed, Fido is immobilized and useless until repaired.', 2),
  ('ng-pd12-fido', 'Utility Mini-Arms (2, small)', 15, 'Each. Small target: Called Shot, -4 to strike.', 3),
  ('ng-pd12-fido', 'Legs, Front (2)', 70, 'Each. Small target: Called Shot, -4 to strike, -8 against a running drone. Speed falls 20% with one leg lost, 50% with two and 90% with three; all four lost immobilize it.', 4),
  ('ng-pd12-fido', 'Legs, Back (2)', 90, 'Each. Small target: Called Shot, -4 to strike, -8 against a running drone. Speed falls 20% with one leg lost, 50% with two and 90% with three; all four lost immobilize it.', 5),
  ('ng-pd12-fido', 'Main Body', 110, 'Reduced to zero, the drone is destroyed beyond repair.', 6),
  ('ng-cdh30-mule', 'Camera Eyes (4, two front and two back)', 5, 'Each. Small target: Called Shot, -4 to strike.', 1),
  ('ng-cdh30-mule', 'Sensor Pod (1, under table)', 35, 'Under the table at one long end: hard to see, and -8 to strike, Called Shot or not. Holds all communications, optics, computers and transmitters; destroyed, the Mule is immobilized and useless until it is replaced.', 2),
  ('ng-cdh30-mule', 'Lights (4, two at each end, under table)', 5, 'Each. Under the table: hard to see, and -8 to strike, Called Shot or not.', 3),
  ('ng-cdh30-mule', 'Robot Legs (6, or 8 on the large NG-CDH33)', 70, 'Each; 100 each on the large version. Small target: Called Shot, -4 to strike, -6 against a running drone. Speed falls 20% with one leg lost, 40% with two and 80% with three or four; with all lost it cannot move.', 4),
  ('ng-cdh30-mule', 'Main Body', 150, '300 on the large NG-CDH33. Reduced to zero, the drone is destroyed beyond repair.', 5),
  ('ng-w9-light-labor-drone', 'Hands (2)', 8, 'Each. Small target: Called Shot, -4 to strike.', 1),
  ('ng-w9-light-labor-drone', 'Arms (2)', 20, 'Each. Small target: Called Shot, -4 to strike.', 2),
  ('ng-w9-light-labor-drone', 'Laser Finger (1, on one hand)', 2, 'Small target: Called Shot, -4 to strike.', 3),
  ('ng-w9-light-labor-drone', 'Legs (2)', 40, 'Each.', 4),
  ('ng-w9-light-labor-drone', 'Head', 40, 'Small target: Called Shot, -2 to strike. Holds all optics and sensors; destroyed, the robot usually shuts down, but one time in ten it goes berserk, lashing out and firing blindly with no combat bonuses and -10 to strike, parry and dodge.', 5),
  ('ng-w9-light-labor-drone', 'Main Body', 100, 'Reduced to zero, the drone is destroyed beyond repair.', 6),
  ('ng-w10-heavy-labor-drone', 'Hand (1)', 10, 'Small target: Called Shot, -4 to strike.', 1),
  ('ng-w10-heavy-labor-drone', 'Laser Claw Hand (1)', 20, 'Small target: Called Shot, -4 to strike.', 2),
  ('ng-w10-heavy-labor-drone', 'Arms (2)', 30, 'Each.', 3),
  ('ng-w10-heavy-labor-drone', 'Legs (2)', 55, 'Each.', 4),
  ('ng-w10-heavy-labor-drone', 'Head', 60, 'Small target: Called Shot, -4 to strike. Holds all optics and sensors; destroyed, the robot usually shuts down, but about two times in ten it keeps flailing, and one with a combat program fights blindly with no bonuses.', 5),
  ('ng-w10-heavy-labor-drone', 'Main Body', 120, 'Reduced to zero, the robot is left as scrap metal.', 6),
  ('ng-wd71-robosistant', 'Head/Sensors', 90, 'Small target: Called Shot, -3 to strike. Destroyed, all optics and sensors are lost.', 1),
  ('ng-wd71-robosistant', 'Headlight (1, top of head)', 8, 'Small target: Called Shot, -3 to strike.', 2),
  ('ng-wd71-robosistant', 'Chest Lights (2)', 5, 'Each. Small target: Called Shot, -3 to strike.', 3),
  ('ng-wd71-robosistant', 'Arms (2)', 90, 'Each. Small target: Called Shot, -3 to strike.', 4),
  ('ng-wd71-robosistant', 'Hands (2)', 12, 'Each. Small target: Called Shot, -3 to strike.', 5),
  ('ng-wd71-robosistant', 'Legs (2)', 115, 'Each. Small target: Called Shot, -3 to strike.', 6),
  ('ng-wd71-robosistant', 'Main Body', 125, 'Reduced to zero, the robot shuts down for good and is useless.', 7);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-pd12-fido', 1, 'Trail Cutting Lasers (2)', '2D6 S.D.C., 5D6 S.D.C., 1D6x10 S.D.C. or 1 M.D. per blast; linked fire possible', 1, '20 ft (6.1 m)', 'Four attacks per melee; a single or dual blast is one attack. The controller''s own attacks do not change the drone''s.', 'Unlimited', NULL, 'They swing out of the cheek housings, which also hold cameras and turn 360 degrees. Primary purpose cutting trails and opening packages; secondary, self-defense, fired only on a voice command from the owner or one of three authorized users.'),
  ('ng-w9-light-labor-drone', 1, 'Laser Finger Gun (1)', '6D6 S.D.C., 1D6x10 S.D.C. or 1D4 M.D.', 1, '100 ft (30.5 m)', 'Each blast is one melee attack', 'Effectively unlimited', NULL, 'A labor tool for cutting and welding in one finger of one hand; under the labor program it is never used as a weapon.'),
  ('ng-w9-light-labor-drone', 2, 'Hand to Hand (labor program)', 'None: it will not strike a living being', 0, 'Melee', 'Three actions per melee', NULL, 'None; unmodified rolls only', 'It may parry, dodge or disarm an attacker, but cannot use guns, clubs or any weapon or tool to hurt anyone.'),
  ('ng-w9-light-labor-drone', 3, 'Hand to Hand (optional military combat program)', 'Restrained punch 6D6 S.D.C.; full punch, elbow or knee 1D4 M.D.; power punch 2D4 M.D. (counts as two attacks); head butt 1D4x10 S.D.C.; kick 2D4 M.D.; body flip or block 1D6 M.D.; no jump kick', 1, 'Melee', 'Four attacks per melee, about Hand to Hand: Expert at 5th level', NULL, '+1 initiative, +3 strike, +4 parry, +4 dodge (+5 running), +2 disarm, +2 roll with impact, +2 pull punch; ranged weapons +3 strike, +4 on an Aimed Shot, +1 with a burst; Vibro-Blade, knife or sword +4 strike and +6 parry', 'Only once the labor program is replaced by NG''s combat program (325,000 credits). The bonus list also makes it immune to S.D.C. attacks, Bio-Manipulation, charms, magic or psionic mind control, and poison, gas or germ agents.'),
  ('ng-w10-heavy-labor-drone', 1, 'Laser Claw Hand (1)', '1D6x10 S.D.C., 1D6 M.D., 2D6 M.D. or 4D6 M.D.', 1, '200 ft (61 m) as set; a simple manual adjustment gives weapon range, 1,600 ft (488 m)', 'Each blast is one melee attack', 'Effectively unlimited', NULL, 'The left hand: a three-fingered claw for digging, tearing down structures and breaking rock, with a heavy laser in the same arm for cutting rock, metal and debris and for welding. A tool under the labor program, never a weapon.'),
  ('ng-w10-heavy-labor-drone', 2, 'Hand to Hand (labor program)', 'None: it will not strike a living being', 0, 'Melee', 'Three actions per melee', NULL, NULL, 'It may parry, dodge and disarm an attacker, but cannot use guns or any weapon or tool to hurt anyone.'),
  ('ng-w10-heavy-labor-drone', 3, 'Hand to Hand (optional military combat program)', 'Restrained punch 1D4 M.D.; full punch, elbow or knee 2D4 M.D.; power punch 2D8 M.D., or 2D8+4 M.D. with the claw (each counts as two attacks); crush, pry or tear 2D6 M.D.; dig 2D6 M.D.; power dig 3D4 M.D.; head butt 1D6x10 S.D.C.; kick 2D8 M.D.; body flip or block 1D8 M.D.; no jump kick', 1, 'Melee', 'Six attacks per melee, about Hand to Hand: Expert at 5th level', NULL, '+1 initiative, +3 strike, +4 parry, +4 dodge (+5 running), +2 disarm, +2 roll with impact, +2 pull punch; ranged weapons +3 strike, +4 on an Aimed Shot, +1 with a burst; Vibro-Blade, knife or sword +4 strike and +6 parry', 'Only after reprogramming as for the NG-W9; it then fights with fists, claw or a handheld weapon. The bonus list also makes it immune to S.D.C. attacks, Bio-Manipulation, charms, magic or psionic mind control, and poison, gas or germ agents.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 5 machines are in' AS assertion, count(*) AS got, 5 AS want
  FROM vehicles WHERE slug IN ('ng-pd12-fido', 'ng-cdh30-mule', 'ng-w9-light-labor-drone', 'ng-w10-heavy-labor-drone', 'ng-wd71-robosistant');
SELECT 'their 30 locations are in' AS assertion, count(*) AS got, 30 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-pd12-fido', 'ng-cdh30-mule', 'ng-w9-light-labor-drone', 'ng-w10-heavy-labor-drone', 'ng-wd71-robosistant');
SELECT 'their 7 weapon entries are in' AS assertion, count(*) AS got, 7 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-pd12-fido', 'ng-cdh30-mule', 'ng-w9-light-labor-drone', 'ng-w10-heavy-labor-drone', 'ng-wd71-robosistant');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-pd12-fido', 'ng-cdh30-mule', 'ng-w9-light-labor-drone', 'ng-w10-heavy-labor-drone', 'ng-wd71-robosistant') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~330-northern-gun-2-drones-b.sql');
